import json
import re
import sys

sys.stdout.reconfigure(encoding='utf-8')

qcache_path = r"C:\Users\melwa\.gemini\antigravity\scratch\mutashabihat-app\quran_cache.json"
output_path = r"C:\Users\melwa\.gemini\antigravity\scratch\mutashabihat-app\zukhruf_scholarly_verified.json"

with open(qcache_path, "r", encoding="utf-8") as f:
    qcache = json.load(f)

def get_surah_info(s_num):
    s = qcache[str(s_num)]
    name = s['name'].replace('سُورَةُ ', '')
    return {
        'surah': name,
        'surahName': f"سورة {name}",
        'ayahs': {a['numberInSurah']: a for a in s['ayahs']}
    }

def get_quarter_str(hq):
    hizb = (hq - 1) // 4 + 1
    rub = (hq - 1) % 4 + 1
    return f"الحزب {hizb} • الربع {rub}"

def make_verse(surah_num, ayah_num, text_html, key_phrase, tokens, context_note=""):
    sinfo = get_surah_info(surah_num)
    adata = sinfo['ayahs'][ayah_num]
    hq = adata['hizbQuarter']
    page = adata['page']
    juz = adata['juz']
    quarter_str = get_quarter_str(hq)
    
    return {
        "surah": sinfo['surah'],
        "surahName": sinfo['surahName'],
        "ayah": ayah_num,
        "page": page,
        "juz": juz,
        "quarter": quarter_str,
        "pos": f"الآية {ayah_num}",
        "textHtml": text_html,
        "html": text_html,
        "keyPhrase": key_phrase,
        "tokens": tokens,
        "contextNote": context_note
    }

